create or replace function public.dreem_enable_verified_auth_channel(p_school_id uuid,p_channel text)returns uuid language plpgsql security definer set search_path='' as $$declare u record;v_endpoint text;v_id uuid;begin if p_channel not in('email','sms','whatsapp')then raise exception 'Only email, SMS or WhatsApp can use verified account contacts';end if;if not private.dreem_is_member(p_school_id)then raise exception 'School membership required';end if;select email,email_confirmed_at,phone,phone_confirmed_at into u from auth.users where id=(select auth.uid());if p_channel='email'then if u.email is null or u.email_confirmed_at is null then raise exception 'A verified account email is required';end if;v_endpoint:=u.email;else if u.phone is null or u.phone_confirmed_at is null then raise exception 'A verified account phone is required';end if;v_endpoint:=u.phone;end if;insert into public.dreem_notification_endpoints(school_id,user_id,channel,endpoint,enabled,verified,verified_at)values(p_school_id,(select auth.uid()),p_channel,v_endpoint,true,true,now())on conflict(school_id,user_id,channel,endpoint)do update set enabled=true,verified=true,verified_at=now(),updated_at=now()returning id into v_id;insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(p_school_id,(select auth.uid()),'notification.channel_enabled','notification_endpoint',v_id,jsonb_build_object('channel',p_channel));return v_id;end;$$;
revoke all on function public.dreem_enable_verified_auth_channel(uuid,text) from public;grant execute on function public.dreem_enable_verified_auth_channel(uuid,text) to authenticated;
create or replace function public.dreem_disable_notification_channel(p_school_id uuid,p_channel text)returns integer language plpgsql security definer set search_path='' as $$declare v_count integer;begin update public.dreem_notification_endpoints set enabled=false,updated_at=now()where school_id=p_school_id and user_id=(select auth.uid())and channel=p_channel;get diagnostics v_count=row_count;insert into public.audit_events(school_id,actor_id,action,entity_type,detail)values(p_school_id,(select auth.uid()),'notification.channel_disabled','notification_endpoint',jsonb_build_object('channel',p_channel,'count',v_count));return v_count;end;$$;
revoke all on function public.dreem_disable_notification_channel(uuid,text) from public;grant execute on function public.dreem_disable_notification_channel(uuid,text) to authenticated;